import React, { useState, useEffect } from 'react';
import { useBrowserHijacking } from '../hooks/useBrowserHijacking';

interface ScarewarePersistenceProps {
  onEscape: () => void;
  onLearnMore: () => void;
}

const ScarewarePersistence: React.FC<ScarewarePersistenceProps> = ({ onEscape, onLearnMore }) => {
  const [layerCount, setLayerCount] = useState(0);

  // Use real scareware browser hijacking techniques
  const { blockedAttempts, isFullscreen } = useBrowserHijacking({
    forceFullscreen: true,
    preventEscape: true,
    preventTabSwitch: true,
    preventMouseEvents: true,
    preventWindowControl: true,
    delayStart: 1000 // 1 second delay to allow layers to start building
  });

  useEffect(() => {
    // Real scareware technique: Create multiple overlay layers
    const addLayer = () => {
      if (layerCount < 5) {
        setLayerCount(prev => prev + 1);
        setTimeout(addLayer, 2000);
      }
    };

    // Start the attack sequence
    setTimeout(() => {
      addLayer();
    }, 1000);
  }, [layerCount]);

  const handleEscape = () => {
    onEscape();
  };

  const handleLearnMore = () => {
    onLearnMore();
  };

  return (
    <>
      {/* Multiple overlay layers - real scareware technique */}
      {Array.from({ length: layerCount }, (_, index) => (
        <div
          key={index}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: `rgba(255, 0, 0, ${0.1 + index * 0.1})`,
            zIndex: 10000 + index,
            pointerEvents: index === layerCount - 1 ? 'auto' : 'none',
          }}
        >
          {index === layerCount - 1 && (
            <div style={{ 
              textAlign: 'center', 
              padding: '2rem',
              color: 'white',
              textShadow: '2px 2px 4px rgba(0,0,0,0.8)'
            }}>
              <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🚨</div>
              <h1 style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>
                SYSTEM COMPROMISED!
              </h1>
              <div style={{ fontSize: '1.2rem', marginBottom: '1rem' }}>
                Layer {layerCount} of protection bypassed!
              </div>
              <div style={{ fontSize: '1rem', marginBottom: '2rem' }}>
                Your computer is under attack by {47 + layerCount * 10} viruses!
              </div>
              
              <div style={{ 
                background: 'rgba(255, 255, 255, 0.2)', 
                padding: '1rem', 
                borderRadius: '8px',
                marginBottom: '2rem'
              }}>
                <div style={{ fontSize: '1.1rem', marginBottom: '1rem' }}>
                  <strong>IMMEDIATE ACTION REQUIRED:</strong>
                </div>
                <div style={{ fontSize: '1rem' }}>
                  Call: 1-800-FAKE-SUPPORT
                  <br />
                  Or pay: $99.99 for immediate protection
                </div>
              </div>

              <div style={{ 
                background: 'rgba(255, 255, 255, 0.3)', 
                padding: '1rem', 
                borderRadius: '8px',
                marginBottom: '2rem',
                fontSize: '0.9rem'
              }}>
                <strong>SIMULATION MODE:</strong> This demonstrates real scareware persistence.
                <br />
                <strong>Blocked escape attempts: {blockedAttempts}</strong>
                <br />
                <strong>Fullscreen mode: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
                <br />
                <strong>Overlay layers: {layerCount}</strong>
              </div>

              <div style={{ marginTop: '2rem' }}>
                <button 
                  className="button button-success" 
                  onClick={handleEscape}
                  style={{ 
                    fontSize: '1.2rem', 
                    padding: '1rem 2rem', 
                    marginRight: '1rem',
                    background: '#28a745',
                    border: '3px solid #fff',
                    boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
                  }}
                >
                  🚪 Emergency Escape (Simulation)
                </button>
                <button 
                  className="button button-primary" 
                  onClick={handleLearnMore}
                  style={{ 
                    fontSize: '1.2rem', 
                    padding: '1rem 2rem',
                    background: '#007bff',
                    border: '3px solid #fff',
                    boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
                  }}
                >
                  📚 Learn More
                </button>
              </div>
            </div>
          )}
        </div>
      ))}

      {/* Persistent popup that keeps appearing */}
      <div 
        style={{
          position: 'fixed',
          top: '20px',
          left: '20px',
          background: 'white',
          border: '3px solid #ff0000',
          borderRadius: '8px',
          padding: '1rem',
          zIndex: 20000,
          boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
          animation: 'shake 0.5s infinite',
          maxWidth: '300px'
        }}
      >
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>⚠️</div>
          <div style={{ fontWeight: 'bold', color: '#ff0000', marginBottom: '0.5rem' }}>
            URGENT ALERT!
          </div>
          <div style={{ fontSize: '0.8rem', marginBottom: '1rem' }}>
            System compromised!
            <br />
            <strong>SIMULATION MODE</strong>
          </div>
          <button 
            onClick={handleEscape}
            style={{
              background: '#ff0000',
              color: 'white',
              border: 'none',
              padding: '0.5rem 1rem',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Fix Now
          </button>
        </div>
      </div>
    </>
  );
};

export default ScarewarePersistence;
